<template>
  <v-dialog v-model="show" persistent max-width="90000">
    <v-card>
      <!-- <v-card-title class="headline">
        {{ dialogInfo.title }}
      </v-card-title>
      <v-card-text>{{ dialogInfo.text }}</v-card-text> -->
      <div class="d-flex flex-column justify-center align-center ">
        <h2
          class="
                      portfolio-modal-title
                      text-secondary text-uppercase
                      mb-0 mt-4 pt-5
                    "
        >
          {{ $t('dialog.title') }}
        </h2>
        <div class="divider-custom">
          <div class="divider-custom-line"></div>
          <div class="divider-custom-icon">
            <i class="fas fa-star"></i>
          </div>
          <div class="divider-custom-line"></div>
        </div>

        <qriously :value="dialogInfo.link" :size="400" />
        <p class="pb-5 px-4 text-center">{{ $t('dialog.text') }}</p>
      </div>
      <v-card-actions>
        <v-spacer></v-spacer>
        <v-btn color="green darken-1" text @click="show = false">
          {{ $t('dialog.close') }}
        </v-btn>
        <v-btn color="green darken-1" text @click="sendSticker(dialogInfo.link)">
          {{ $t('dialog.readFarewell') }}
        </v-btn>
      </v-card-actions>
    </v-card>
  </v-dialog>
</template>

<script>
export default {
  props: {
    dialogInfo: Object,
    value: Boolean,
  },
  computed: {
    show: {
      get() {
        return this.value;
      },
      set(value) {
        this.$emit('input', value);
      },
    },
  },
  methods: {
    sendSticker(link) {
      console.log(link);
      window.open(link);
    },
  },
};
</script>

