<template>
<v-card
    @click="routeToCategory(card.categoryName)"
    class="mx-auto"
    max-width="400"
  >
    <v-img
      class="white--text align-end"
      height="200px"
      :src="card.categoryImageURL"
    >
      <v-card-title>{{card.categoryName}}</v-card-title>
    </v-img>
</v-card>
</template>

<script>
export default {
  props: {
    card: Object,
  },
  methods: {
    routeToCategory(catName) {
      this.$router.push({ name: 'Category', params: { categoryName: catName } });
    },
  },
};
</script>

