<template>
<v-container>
        <v-row>
          <v-col
            v-for="stickercard in StickerCards ? StickerCards : 9"
            :key="stickercard.stickerName"
            cols="12"
            md="3"
          >
            <div v-if="!loading" >
              <StickerCard  :stickercard="stickercard"/>
            </div>
            <div v-else>
                <v-skeleton-loader
                class="mx-auto"
                max-width="300"
                type="card" >
                </v-skeleton-loader>
            </div>
          </v-col>
        </v-row>
      </v-container>
</template>

<script>
import StickerCard from './StickerCard.vue';
import { db } from '../firebase';

export default {
  name: 'StickerCards',
  components: {
    StickerCard,
  },
  props: {
    category: String,
    isPlus18: Boolean,
  },
  data() {
    return {
      loading: true,
      StickerCards: [],
      db,
    };
  },
  watch: {
    isPlus18() {
      this.getCards();
    },
  },
  computed: {
    dynLinkc() {
      return this.dialogInfo.link;
    },
  },
  methods: {
    getCards() {
      if (this.isPlus18) {
        db.collection('stickers').where('category', '==', this.category).where('tags', 'array-contains', '+18').get()
          .then((querySnapshot) => {
            const documents = querySnapshot.docs.map((doc) => ({ id: doc.id, ...doc.data() }));
            this.StickerCards = documents;
            setTimeout(() => {
              this.loading = false;
            }, 800);
          });
      } else {
        db.collection('stickers').where('category', '==', this.category).where('isPlus18', '==', false).get()
          .then((querySnapshot) => {
            const documents = querySnapshot.docs.map((doc) => ({ id: doc.id, ...doc.data() }));
            this.StickerCards = documents;
            setTimeout(() => {
              this.loading = false;
            }, 800);
          });
      }
    },
  },
  created() {
    this.getCards();
  },
};
</script>

